using System.Collections.Generic;
using UnityEngine;

namespace SpectreEX
{
    // Plays the original Spectre VR MIDI soundtrack (rendered to OGG through GeneralUser GS by
    // Tools/fluid_render.py, generated by Tools/import_original.py). Each level plays its matrix song in the
    // styles ticked in Options; the menu plays 5THEME (song 24001). M toggles music.
    public class MusicPlayer : MonoBehaviour
    {
        static MusicPlayer instance;
        public static MusicPlayer Instance
        {
            get
            {
                if (instance == null) instance = FindFirstObjectByType<MusicPlayer>();
                return instance;
            }
            private set => instance = value;
        }

        public float volume = 0.45f;
        const string MenuTheme = "5THEME";

        AudioSource source;
        bool muted;

        void Awake()
        {
            Instance = this;
            source = gameObject.AddComponent<AudioSource>();
            source.spatialBlend = 0f;
            source.loop = true;
            source.volume = volume;
            source.ignoreListenerPause = true;
        }

        public void PlayMenuTheme()
        {
            if (!GameSettings.MusicOn) source.Stop();
            else if (source.clip == null || source.clip.name != MenuTheme || !source.isPlaying) PlayTrack(MenuTheme);
        }

        public void Stop() => source.Stop();

        // A matrix level's song (null = the level has none, or no ticked style covers it)
        public void PlayTrackOrStop(string name)
        {
            if (string.IsNullOrEmpty(name)) source.Stop();
            else PlayTrack(name);
        }

        public void PlayTrack(string name, bool loop = true)
        {
            if (!GameSettings.MusicOn) { source.Stop(); return; }
            var clip = Resources.Load<AudioClip>("Music/" + name);
            if (clip == null) { Debug.LogWarning("Spectre VR-EX: missing music " + name); return; }
            source.clip = clip;
            source.loop = loop;
            if (!muted) source.Play();
        }

        void Update()
        {
            if (GameKeys.Music.Pressed)
            {
                muted = !muted;
                if (muted) source.Pause(); else source.UnPause();
                if (!muted && !source.isPlaying) source.Play();
            }
        }
    }
}
